#!/usr/bin/env bash
#
# End-to-end benchmark of the distributedRateLimit plugin behind Traefik.
#
# The stands live in hack/bench (Traefik v3.5 + traefik/whoami + Redis; Redis is
# never published on the host). Load is generated by the stdlib-only program in
# hack/bench/loadgen, in two ways:
#
#   * from the host, through the published ports (18000/18080) — what a client
#     outside the docker network observes, and the configuration the task asks
#     for;
#   * from a container inside the same network — which removes the docker
#     Desktop port-forwarding cost and shows the plugin without that ceiling.
#
# Cases (client-side RPS and latency percentiles, each WARMUP + DURATION):
#
#   1. single, plugin disabled (limit 0)        — control: Traefik + whoami only
#   2. single, everything allowed               — the plugin's cost on the hot path
#   3. single, everything allowed + headers     — cost of the X-RateLimit-* headers
#   4. single, low limit                        — the deny path under load
#   5. single, in-network, allowed              — the plugin without port forwarding
#   6. single, in-network, allowed + headers
#   7. single, in-network, low limit
#   8. single, in-network, allowed, DEFAULT pool — what the default poolSize does
#      under concurrency: connection churn, ephemeral port exhaustion, breaker
#   9. two instances sharing one Redis, in-network, low limit
#                                               — the limit must hold cluster-wide
#
# Cases 1-7 and 9 set store.redis.poolSize/maxActiveConns to the worker count, so
# that the numbers describe the plugin itself and not the connection churn of the
# default pool (5). Case 8 deliberately keeps the default, to show the failure it
# causes; the store error is captured from the Traefik log for each case.
#
# Requirements: docker (compose), go, curl.
#
#   ./hack/bench/run.sh
#   BENCH_WORKERS=64 BENCH_DURATION=15s ./hack/bench/run.sh
#
# Knobs: BENCH_WORKERS (32), BENCH_DURATION (10s), BENCH_WARMUP (2s),
#        BENCH_LIMIT_HIGH, BENCH_LIMIT_LOW, BENCH_TIMEOUT, BENCH_POOL (worker
#        count), BENCH_KEEP=1.

set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_DIR="$(cd "$HERE/../.." && pwd)"

SINGLE_COMPOSE="$HERE/docker-compose.single.yaml"
DUAL_COMPOSE="$HERE/docker-compose.dual.yaml"

WORKERS="${BENCH_WORKERS:-32}"
DURATION="${BENCH_DURATION:-10s}"
WARMUP="${BENCH_WARMUP:-2s}"
TIMEOUT="${BENCH_TIMEOUT:-5s}"
LIMIT_HIGH="${BENCH_LIMIT_HIGH:-10000000}"
LIMIT_LOW="${BENCH_LIMIT_LOW:-100}"
POOL="${BENCH_POOL:-$WORKERS}"
SOURCE_HEADER="X-Sm-User-Id: bench-user"

WORK="$(mktemp -d)"
CONF_DIR="$WORK/conf"
mkdir -p "$CONF_DIR"

export BENCH_CONF_DIR="$CONF_DIR"
export BENCH_PLUGIN_DIR="$PLUGIN_DIR"
export BENCH_BIN_DIR="$WORK"

ROWS=()
LAST_STORE_ERROR=""

cleanup() {
	local status=$?

	docker compose -f "$SINGLE_COMPOSE" --profile tools down -v --remove-orphans >/dev/null 2>&1 || true
	docker compose -f "$DUAL_COMPOSE" --profile tools down -v --remove-orphans >/dev/null 2>&1 || true

	if [[ "${BENCH_KEEP:-0}" == "1" ]]; then
		echo "raw output kept in $WORK"
	else
		rm -rf "$WORK"
	fi

	exit "$status"
}
trap cleanup EXIT

# ---------------------------------------------------------------------------
# Configuration of the stands
# ---------------------------------------------------------------------------

write_static_conf() {
	cat >"$CONF_DIR/traefik.yaml" <<'YAML'
entryPoints:
  web:
    address: ":8000"

providers:
  file:
    filename: /etc/traefik/dynamic.yaml

api:
  insecure: true

log:
  level: INFO

experimental:
  localPlugins:
    distributedRateLimit:
      moduleName: github.com/MichNG/traefik-distributed-rate-limit
YAML
}

# write_dynamic_conf <limit> <burst> <responseHeaders> [poolSize]
write_dynamic_conf() {
	local limit="$1" burst="$2" headers="$3" pool="${4:-}"

	local pool_lines=""
	if [[ -n "$pool" ]]; then
		pool_lines="              poolSize: ${pool}
              maxActiveConns: ${pool}"
	fi

	cat >"$CONF_DIR/dynamic.yaml" <<YAML
http:
  routers:
    bench:
      rule: "PathPrefix(\`/\`)"
      entryPoints:
        - web
      middlewares:
        - distributed-ratelimit
      service: target

  middlewares:
    distributed-ratelimit:
      plugin:
        distributedRateLimit:
          limit: ${limit}
          period: 1s
          burst: ${burst}
          denyOnError: true
          responseHeaders: ${headers}
          sourceCriterion:
            requestHeaderName: X-Sm-User-Id
          store:
            redis:
              endpoints:
                - redis:6379
              timeout: 1s
${pool_lines}

  services:
    target:
      loadBalancer:
        servers:
          - url: http://target
YAML
}

# ---------------------------------------------------------------------------
# Stand lifecycle
# ---------------------------------------------------------------------------

up_stand() {
	local compose="$1"
	shift
	local services=("$@")

	docker compose -f "$compose" up -d >/dev/null

	local svc
	for svc in "${services[@]}"; do
		local loaded=0
		for _ in $(seq 1 60); do
			if docker compose -f "$compose" logs --no-log-prefix "$svc" 2>/dev/null | grep -q "Plugins loaded"; then
				loaded=1
				break
			fi
			sleep 0.5
		done

		if [[ "$loaded" != "1" ]]; then
			echo "FATAL: the plugin did not load in $svc" >&2
			docker compose -f "$compose" logs --no-log-prefix "$svc" | tail -20 >&2
			return 1
		fi
	done
}

# wait_ready <compose> <service> <url> [loud]
wait_ready() {
	local compose="$1" service="$2" url="$3" loud="${4:-1}"

	for _ in $(seq 1 40); do
		if curl -fsS -o /dev/null -H "X-Sm-User-Id: bench-user" "$url" 2>/dev/null; then
			return 0
		fi
		sleep 0.5
	done

	if [[ "$loud" == "1" ]]; then
		echo "FATAL: $url is not answering" >&2
		echo "--- traefik log ($service) ---" >&2
		docker compose -f "$compose" logs --no-log-prefix "$service" | tail -30 >&2
		echo "--- routers seen by the API ---" >&2
		curl -sS http://127.0.0.1:18080/api/http/routers | head -c 2000 >&2 || true
		echo >&2
		return 1
	fi

	echo "WARNING: $url did not answer during the readiness check" >&2
	return 0
}

# A hot reload of the file provider is how Traefik applies a new middleware
# configuration: the middleware instance is retired and rebuilt. Wait for it,
# then give the router a moment to answer again.
apply_conf() {
	local compose="$1" url="$2"

	sleep 2
	wait_ready "$compose" "" "$url" 0
}

# ---------------------------------------------------------------------------
# Evidence helpers
# ---------------------------------------------------------------------------

# redis_connections <compose> — cumulative connections accepted by Redis.
redis_connections() {
	docker compose -f "$1" exec -T redis redis-cli info stats 2>/dev/null |
		sed -n 's/^total_connections_received:\([0-9]*\).*/\1/p' | tr -d '\r'
}

# store_errors_since <compose> <timestamp> <service...> — plugin store errors.
store_errors_since() {
	local compose="$1" since="$2"
	shift 2

	docker compose -f "$compose" logs --no-log-prefix --since "$since" "$@" 2>/dev/null |
		sed 's/\x1b\[[0-9;]*m//g' | grep "no rate limit decision" || true
}

# ---------------------------------------------------------------------------
# Load and reporting
# ---------------------------------------------------------------------------

parse_out() {
	local out="$1"

	P_REQUESTS="$(sed -n 's/^requests=\([0-9]*\).*/\1/p' "$out")"
	P_200="$(sed -n 's/^requests=[0-9]* status_200=\([0-9]*\).*/\1/p' "$out")"
	P_429="$(sed -n 's/^requests=[0-9]* status_200=[0-9]* status_429=\([0-9]*\).*/\1/p' "$out")"
	P_RPS="$(sed -n 's/^rps=//p' "$out")"
	P_P50="$(sed -n 's/^lat_ms_min=[0-9.]* p50=\([0-9.]*\).*/\1/p' "$out")"
	P_P95="$(sed -n 's/.* p95=\([0-9.]*\).*/\1/p' "$out")"
	P_P99="$(sed -n 's/.* p99=\([0-9.]*\).*/\1/p' "$out")"
}

# report_case <label> <compose> <service> <limit> <burst> <headers> <pool> <urls> <out> [note] [extra]
report_case() {
	local label="$1" compose="$2" service="$3" limit="$4" burst="$5" headers="$6" pool="$7" urls="$8" out="$9"
	local note="${10:-}" extra="${11:-}"

	parse_out "$out"

	local per_url=""
	per_url="$(sed -n 's/^url\([0-9]*\)_status_200=\([0-9]*\).*/\1:\2/p' "$out")"
	if [[ "$(printf '%s\n' "$per_url" | grep -c .)" -le 1 ]]; then
		per_url=""
	else
		per_url="$(printf '%s\n' "$per_url" | paste -sd' ' -)"
	fi

	local store_errs="${STORE_ERR_COUNT:-0}"

	ROWS+=("$label|$P_RPS|$P_P50|$P_P95|$P_P99|$P_200|$P_429|$P_REQUESTS|$per_url|$store_errs|$note")

	echo
	echo "== $label =="
	echo "   limit=$limit/s burst=$burst responseHeaders=$headers pool=${pool:-default} urls: $urls"
	echo "   $(sed -n '1,3p' "$out" | tr -s '\n' ' ')"

	if [[ -n "$per_url" ]]; then
		echo "   per instance (url_index:200): $per_url"
	fi
	if [[ -n "$extra" ]]; then
		echo "   $extra"
	fi
	if [[ -n "$note" ]]; then
		echo "   $note"
	fi
	if [[ -n "$LAST_STORE_ERROR" ]]; then
		echo "   store errors: ${STORE_ERR_COUNT:-?} (first: $LAST_STORE_ERROR)"
	fi
}

# run_case <label> <compose> <service> <urls> <limit> <burst> <headers> <pool> <mode> <ready-url> [note]
run_case() {
	local label="$1" compose="$2" service="$3" urls="$4" limit="$5" burst="$6" headers="$7" pool="$8" mode="$9" ready_url="${10}"
	local note="${11:-}"

	write_dynamic_conf "$limit" "$burst" "$headers" "$pool"
	apply_conf "$compose" "$ready_url"

	local args=()
	local url
	for url in $urls; do
		args+=(-url "$url")
	done

	local out="$WORK/${label//\//-}.txt"
	local start conns_before conns_after
	start="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
	conns_before="$(redis_connections "$compose")"

	if [[ "$mode" == "net" ]]; then
		docker compose -f "$compose" --profile tools run --rm -T loadgen "${args[@]}" \
			-workers "$WORKERS" -duration "$DURATION" -warmup "$WARMUP" -timeout "$TIMEOUT" \
			-header "$SOURCE_HEADER" >"$out"
	else
		"$WORK/loadgen" "${args[@]}" \
			-workers "$WORKERS" -duration "$DURATION" -warmup "$WARMUP" -timeout "$TIMEOUT" \
			-header "$SOURCE_HEADER" >"$out"
	fi

	conns_after="$(redis_connections "$compose")"

	local errors
	errors="$(store_errors_since "$compose" "$start" $service)"
	STORE_ERR_COUNT="$(printf '%s\n' "$errors" | grep -c . || true)"
	LAST_STORE_ERROR="$(printf '%s\n' "$errors" | grep -m1 . | sed 's/.*ERROR //' | cut -c1-220 || true)"
	if [[ "$STORE_ERR_COUNT" == "0" ]]; then
		LAST_STORE_ERROR=""
	fi

	report_case "$label" "$compose" "$service" "$limit" "$burst" "$headers" "$pool" "$urls" "$out" "$note" \
		"new Redis connections during the case: $((conns_after - conns_before))"
}

print_table() {
	echo
	echo "==========================================================================================================="
	echo "SUMMARY (client-side, $WORKERS workers, ${DURATION} measured after ${WARMUP} warmup, pool=$POOL unless noted)"
	echo "==========================================================================================================="
	printf '%-36s %9s %8s %8s %8s %9s %9s %8s\n' "case" "rps" "p50 ms" "p95 ms" "p99 ms" "200" "429" "store err"

	local row
	for row in "${ROWS[@]}"; do
		IFS='|' read -r label rps p50 p95 p99 s200 s429 requests per_url store_errs note <<<"$row"
		printf '%-36s %9s %8s %8s %8s %9s %9s %8s\n' "$label" "$rps" "$p50" "$p95" "$p99" "$s200" "$s429" "$store_errs"
	done

	echo
	echo "per-instance allowed counts:"
	for row in "${ROWS[@]}"; do
		IFS='|' read -r label rps p50 p95 p99 s200 s429 requests per_url store_errs note <<<"$row"
		if [[ -n "$per_url" ]]; then
			local sum
			sum="$(printf '%s\n' "$per_url" | tr ' ' '\n' | cut -d: -f2 | paste -sd+ - | bc)"
			echo "  $label: $per_url (sum $sum)"
		fi
	done
}

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

echo "building the load generator (host + linux/arm64 for the in-network runs)..."
go build -o "$WORK/loadgen" "$PLUGIN_DIR/hack/bench/loadgen"
CGO_ENABLED=0 GOOS=linux GOARCH=arm64 go build -o "$WORK/loadgen-linux" "$PLUGIN_DIR/hack/bench/loadgen"

write_static_conf
write_dynamic_conf "$LIMIT_HIGH" "$LIMIT_HIGH" false "$POOL"

echo "starting the single-instance stand (Traefik on :18000, API on :18080, Redis internal)..."
up_stand "$SINGLE_COMPOSE" reverse-proxy
wait_ready "$SINGLE_COMPOSE" reverse-proxy "http://127.0.0.1:18000/"

SINGLE_URL="http://127.0.0.1:18000/"
NET_URL="http://reverse-proxy:8000/"

# 1. Control: the plugin is configured but disabled (limit 0), so the run
# measures Traefik + whoami + the docker port forwarding.
run_case "single/limit=0 (control)" "$SINGLE_COMPOSE" reverse-proxy "$SINGLE_URL" 0 0 false "$POOL" host "$SINGLE_URL" \
	"no store call at all: the floor for the host-driven runs"

# 2-3. Everything allowed: the plugin's cost on the hot path, with and without
# the X-RateLimit-* headers.
run_case "single/allow" "$SINGLE_COMPOSE" reverse-proxy "$SINGLE_URL" "$LIMIT_HIGH" "$LIMIT_HIGH" false "$POOL" host "$SINGLE_URL"
run_case "single/allow+headers" "$SINGLE_COMPOSE" reverse-proxy "$SINGLE_URL" "$LIMIT_HIGH" "$LIMIT_HIGH" true "$POOL" host "$SINGLE_URL"

# 4. A low limit: most requests are denied, which exercises the 429 path.
run_case "single/limited(${LIMIT_LOW}/s)" "$SINGLE_COMPOSE" reverse-proxy "$SINGLE_URL" "$LIMIT_LOW" "$LIMIT_LOW" false "$POOL" host "$SINGLE_URL" \
	"expected allowed ~= limit*duration = $((LIMIT_LOW * ${DURATION%s}))"

# 5-7. The same three cases, driven from inside the docker network, where no
# port forwarding stands between the client and Traefik.
run_case "net/allow" "$SINGLE_COMPOSE" reverse-proxy "$NET_URL" "$LIMIT_HIGH" "$LIMIT_HIGH" false "$POOL" net "$SINGLE_URL"
run_case "net/allow+headers" "$SINGLE_COMPOSE" reverse-proxy "$NET_URL" "$LIMIT_HIGH" "$LIMIT_HIGH" true "$POOL" net "$SINGLE_URL"
run_case "net/limited(${LIMIT_LOW}/s)" "$SINGLE_COMPOSE" reverse-proxy "$NET_URL" "$LIMIT_LOW" "$LIMIT_LOW" false "$POOL" net "$SINGLE_URL" \
	"expected allowed ~= limit*duration = $((LIMIT_LOW * ${DURATION%s}))"

# 8. The default pool (5) under the same load: this is where the connection
# churn shows up (and, in the Traefik container, the ephemeral port exhaustion).
run_case "net/allow (default pool) #1" "$SINGLE_COMPOSE" reverse-proxy "$NET_URL" "$LIMIT_HIGH" "$LIMIT_HIGH" false "" net "$SINGLE_URL" \
	"store.redis.poolSize/maxActiveConns left at their defaults (5 / 10*GOMAXPROCS)"

# ...and once more, back to back: this is the run where the ephemeral ports of
# the Traefik container are gone and the breaker turns everything into a 429.
run_case "net/allow (default pool) #2" "$SINGLE_COMPOSE" reverse-proxy "$NET_URL" "$LIMIT_HIGH" "$LIMIT_HIGH" false "" net "$SINGLE_URL" \
	"the same, immediately again: the store errors of the first run are visible here"

echo
echo "redis keys in the single-instance stand:"
docker compose -f "$SINGLE_COMPOSE" exec -T redis redis-cli --scan --pattern 'rate:*' | sed 's/^/  /'

docker compose -f "$SINGLE_COMPOSE" --profile tools down -v --remove-orphans >/dev/null

echo
echo "starting the two-instance stand (Traefik on :18000 and :18001, one shared Redis)..."
write_dynamic_conf "$LIMIT_LOW" "$LIMIT_LOW" true "$POOL"
up_stand "$DUAL_COMPOSE" reverse-proxy-1 reverse-proxy-2
wait_ready "$DUAL_COMPOSE" reverse-proxy-1 "http://127.0.0.1:18000/"
wait_ready "$DUAL_COMPOSE" reverse-proxy-2 "http://127.0.0.1:18001/"

# 9. The same low limit on both instances, from inside the network: the sum of
# the allowed requests must stay at one instance's budget, which is what
# "cluster-wide" means here.
run_case "dual/limited(${LIMIT_LOW}/s)+headers" "$DUAL_COMPOSE" "reverse-proxy-1 reverse-proxy-2" \
	"http://reverse-proxy-1:8000/ http://reverse-proxy-2:8000/" "$LIMIT_LOW" "$LIMIT_LOW" true "$POOL" net "http://127.0.0.1:18000/" \
	"expected total allowed ~= limit*duration = $((LIMIT_LOW * ${DURATION%s})), not 2x"

echo
echo "redis keys in the two-instance stand (one shared bucket per source):"
docker compose -f "$DUAL_COMPOSE" exec -T redis redis-cli --scan --pattern 'rate:*' | sed 's/^/  /'

docker compose -f "$DUAL_COMPOSE" --profile tools down -v --remove-orphans >/dev/null

print_table

echo
echo "raw per-case output: $WORK (BENCH_KEEP=1 keeps it after the run)"
